ngOnInit() {
  const badge = document.createElement('span');
  badge.textContent = this.status;
  this.host.nativeElement.appendChild(badge);
}

@Component({
  selector: 'user-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `{{ user.name }}`
})
export class UserCardComponent {
  @Input() user!: User;
}

// Normalized store
rename(userId: string, nextName: string) {
  const user = this.usersById[userId];
  user.name = nextName;
  this.selectedUser = user;
}

form = new FormGroup({
  email: new FormControl('')
});

submit() {
  if (this.form.invalid) return;
  this.api.createAccount(this.form.value).subscribe();
}

results$ = this.query.valueChanges.pipe(
  debounceTime(200),
  distinctUntilChanged(),
  mergeMap(query => this.http.get<Result[]>('/search', { params: { query } }))
);

async function load() {
  try {
    return Promise.reject('offline');
  } catch {
    console.log('inner-catch');
    return 'cached';
  } finally {
    console.log('inner-finally');
  }
}

load()
  .catch((error) => {
    console.log(`outer:${error}`);
    return 'queued';
  })
  .finally(() => console.log('outer-finally'))
  .then((value) => console.log(`value:${value}`));

if (button.dataset.enabled) {
  runAction();
}

const list = document.createElement('div');
const button = document.createElement('button');
list.append(button);

list.addEventListener('click', (event) => {
  console.log(event.target.tagName);
  console.log(event.currentTarget.tagName);
});

button.click();

Promise.reject('network')
  .catch((error) => {
    console.log(`caught:${error}`);
    return 'cached';
  })
  .finally(() => console.log('cleanup'))
  .then((value) => console.log(`value:${value}`));

Promise.resolve('start')
  .then((value) => {
    console.log(value);
    throw new Error('boom');
  })
  .finally(() => console.log('finally-1'))
  .catch((error) => {
    console.log(error.message);
    return 'recovered';
  })
  .finally(() => {
    console.log('finally-2');
    throw new Error('cleanup');
  })
  .then(
    (value) => console.log(value),
    (error) => console.log(error.message),
  );

console.log('open');

setTimeout(() => {
  console.log('notify');
  queueMicrotask(() => console.log('after-notify'));
}, 0);

setTimeout(() => console.log('archive'), 0);

Promise.resolve().then(() => {
  console.log('validate');
  queueMicrotask(() => console.log('commit'));
});

queueMicrotask(() => console.log('measure'));
console.log('close');

console.log('render');

setTimeout(() => console.log('timer'), 0);

Promise.resolve().then(() => console.log('promise'));

console.log('commit');

