const product = await catalog.read(productId);
return <BuyButton product={product} onBuy={() => cart.add(product.id)} />;

useEffect(() => {
  setStatus('loading');

  fetchSearch(query)
    .then((items) => setResults(items))
    .catch((error) => setError(error))
    .finally(() => setStatus('idle'));
}, [query]);

const AnalyticsWidget = defineAsyncComponent(() =>
  import('./AnalyticsWidget.vue')
)

const ReviewsWidget = defineAsyncComponent({
  loader: () => import('./ReviewsWidget.vue')
})

async setQuantity(id, quantity) {
  const before = this.items[id].quantity
  this.items[id].quantity = quantity
  try {
    await api.saveQuantity(id, quantity)
  } catch {
    this.items[id].quantity = before
  }
}

let currentClient

